use std::{fs,path::Path,collections::BTreeMap,fmt::Write};
use serde_json::{Value,json};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-g2-tree-records";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-27-g2-tree-records";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){
 let r=Path::new(R);let d=Path::new(D);let full=r.join("performance-analysis.json").exists();let stage=if full{"performance"}else{"screen"};
 let a=read(r.join(format!("{stage}-analysis.json")));let screen=read(r.join("screen-analysis.json"));let protocol=read(r.join(stage).join("protocol.json"));
 for(p,h)in protocol["pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap(),"closing pin {p}");}
 let m=read("/tmp/zopro-grouping-module/production-source-manifest.json");for(p,h)in m["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new("/home/ubuntu/src/zk-tools/zopro").join(p)),h.as_str().unwrap());}
 assert_eq!(hash("/tmp/zopro-grouping-module/native/candidate-sdk"),"03e1260e89068c2bec37a2471c34e93628a9f081903e1b7eee9cab9c306aaf3d");
 assert_eq!(read(r.join("native/core/tests.json"))["passed_tests"].as_array().unwrap().len(),110);
 let inventory=read(r.join("proof-inventory.json"));let mut proofs=0;for(p,h)in inventory.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());if p.ends_with(".proof"){assert_eq!(fs::metadata(p).unwrap().len(),164);proofs+=1;}}
 assert_eq!(proofs,a["independent_exports"].as_u64().unwrap());assert_eq!(inventory.as_object().unwrap().len(),proofs as usize*2);
 let close=json!({"status":"G2 existing-tree prefix records SDK study closed","root":R,"source_originals":170,"unchanged_candidate_originals":169,"production_sources_checked_unchanged":170,"native_core_tests":110,"new_core_tests":1,"raw_tests":2,"cubic_tests":6,"field_source_and_qualification_inherited":true,"fresh_control_reused_unchanged":true,"SDK_requests":a["sdk_requests"],"independent_gnark_exports":proofs,"proof_public_members":proofs*2,"prior_count":7260,"next_prior_count":a["next_prior_count"],"full_stage_executed":full,"new_profiles":if full{3}else{0},"screen_advances":screen["screen_advances_to_full"],"full_gate_passed":a["full_gate_passed"],"closing_pins_checked":protocol["pins"].as_object().unwrap().len(),"adopted":false,"goal_achieved":false,"no_successful_capture_repeated":true});save(r.join("closeout.json"),&close);
 let mut md=String::from("# G2 prefix records in existing tree layers\n\n");
 let c=&a["cases"]["1x2-w32"];
 writeln!(md,"Primary32 paired tree/accepted: **{:.6}**; tree/fresh: **{:.6}**. Screen advances: **{}**; full gate passes: **{}**. No change is adopted. Small reliable gains have no minimum cutoff.\n",c["pairs"]["tree/accepted"]["geometric_ratio"].as_f64().unwrap(),c["pairs"]["tree/fresh"]["geometric_ratio"].as_f64().unwrap(),screen["screen_advances_to_full"],a["full_gate_passed"]).unwrap();
 md.push_str("The existing G2 affine-tree layer stores a prefix and norm pair instead of coordinates and scaled numerators. Reverse evaluation rereads each disjoint original pair and combines prefix with inverse before the existing Fq2 numerator formula, removing one elementary field product per full ordinary pair. The record payload falls from nine native vectors to two. This applies the accepted streaming arithmetic ordering to previously unchanged tree layers.\n\nTree topology, tile size, pair selection, scalar tails, exceptional-pair compaction, weighted/indexed/grouped callers, query dispatch and scheduling remain unchanged. G1 keeps its original arithmetic bodies behind a compile-time false branch. Portable and no-IFMA builds retain the original G2 path. Only `msm.rs` changes; reversing the edits recovers the original file, and169 other originals are exact. There is no new key table, copied input array, plan, pool or field primitive.\n\nThis differs from the previous G2 level/prefix-tree experiments, which replaced a streaming query with trees and left generic weighted/top reductions unchanged. It also excludes the G1 prefix-streaming variant that previously regressed. Source review first checked the proposed empty-inverse bypass against the historical operation census: the actual `m==0` counter found no primary empty tree batches. That bypass was not built, and the old counts are not relabeled as a fresh capture.\n\n## Complete verified SDK comparison\n\nRyzen9950X, exact accepted SDK and reused pinned fresh baseline, candidate with identical compiler/native flags/fat LTO/one code-generation unit/standard SDK driver. Baseline source, library and consumer pins are rechecked; no new control build is claimed. Timed requests include witness construction, fresh blinded proving, SDK verification and serialization; loading and primes are excluded. Ratios and savings pair within each rotated/reversed fresh-process block. CPU includes coordination and lifetime RSS includes load/primes; neither isolates kernel service or minimum RAM.\n\n|Case|Accepted ms|Fresh ms|Tree ms|Tree/accepted|Tree/fresh|Paired saving vs fresh µs|Wins vs fresh|Tree RSS MiB|Tree CPU ms/request|\n|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|\n");
 for(name,c)in a["cases"].as_object().unwrap(){let m=&c["modes"];let p=&c["pairs"];writeln!(md,"|{name}|{:.6}|{:.6}|{:.6}|{:.6}|{:.6}|{:.3}|{}|{:.2}|{:.3}|",m["accepted"]["ms"].as_f64().unwrap(),m["fresh"]["ms"].as_f64().unwrap(),m["tree"]["ms"].as_f64().unwrap(),p["tree/accepted"]["geometric_ratio"].as_f64().unwrap(),p["tree/fresh"]["geometric_ratio"].as_f64().unwrap(),p["tree/fresh"]["saving_us"].as_f64().unwrap(),p["tree/fresh"]["wins"],m["tree"]["maxrss_mib"].as_f64().unwrap(),m["tree"]["cpu_ms_per_request"].as_f64().unwrap()).unwrap();}
 md.push_str("\nThe screen has three blocks at primary16/CPUs0–15 and primary32/CPUs0–31,17 timed requests after3 primes per process. Fresh/accepted calibration must stay within factor1.05 each block and factor1.03 for paired medians. Primary32 must improve against both controls with at least2/3 wins, and both cases must stay within2% against both controls. Every sample and failure remains included, without threshold changes or repeated successful captures. Displayed medians and within-block paired comparisons are different summaries; adoption uses the declared paired checks.\n\n");
 for key in ["calibration_failures","primary_failures","regressions"]{writeln!(md,"{key}: `{}`.\n",a[key]).unwrap();}
 if full {
 md.push_str("The full stage follows with seven blocks over all nine shapes at32workers plus primary16, then three warm-gated199Hz cycle profiles after all latency. Its full gate also requires original-eight paired aggregate improvement/tie against both controls, every-case nonregression, and primary32 improvement in at least4/7 blocks.\n\n## Supplied M5 comparisons\n\nHistorical supplied CPU/Metal values; no new M5 measurement or54 reference.\n\n|Shape|Tree ms|M5 CPU ms|CPU speedup|M5 Metal ms|Metal speedup|\n|---|---:|---:|---:|---:|---:|\n");
 for c in a["cases"].as_object().unwrap().values().filter(|c|c["workers"]==32){let ms=c["modes"]["tree"]["ms"].as_f64().unwrap();if let(Some(cpu),Some(metal))=(c["reference"]["cpu_ms"].as_f64(),c["reference"]["metal_ms"].as_f64()){writeln!(md,"|{}|{ms:.6}|{cpu:.0}|{:.3}×|{metal:.0}|{:.3}×|",c["shape"].as_str().unwrap(),cpu/ms,metal/ms).unwrap();}else{writeln!(md,"|{}|{ms:.6}|—|—|—|—|",c["shape"].as_str().unwrap()).unwrap();}}
 } else {assert!(!r.join("performance").exists());md.push_str("The full stage and cycle profiles did not run. The [last complete SDK matrix](../2026-10-26-pairing-x-chain-sdk/README.md) retains all supplied M5 CPU/Metal comparisons outside this short screen.\n\n");}
 md.push_str("## Correctness, memory and limits\n\nAll110 native core tests, two raw tests, six cubic tests, generator and portable/no-IFMA consumer checks pass. The new oracle performs240 full-buffer layer comparisons:24 ascending/descending lengths through2048, five ordinary/identity/doubling/opposite/mixed patterns, two inversion modes and seven empty/odd/even buckets. Expected points use complete scalar curve formulas; every output count and live point is checked, with scratch reuse and unused old-record-buffer assertions. Existing indexed/weighted/generator oracles remain. Field source and its accepted qualification are inherited unchanged.\n\nThe prefix Vec replaces the allocated native G2 Group Vec. Its payload is two320-byte vectors per eight ordinary pairs versus nine previously. One additional empty Vec header exists in Scratch (24bytes on this target); struct padding and allocator behavior are additional considerations. Lower source record bytes are not measured DRAM traffic, whole-process savings or a minimum-RAM claim. Typed workspace forecasts still use the larger record bound; formal metadata/resource/pressure qualification remains necessary before adoption.\n\nThe first setup helper stopped on an exact-match assertion before writing a candidate file: the same reserve expression appeared in tree and streaming code. A tree-specific anchor repaired setup before any native build or SDK call. The original helper and correction note are retained. No arithmetic, protocol or threshold changed in that repair.\n\nPreflight covers all nine candidate shapes at four workers, one timed request plus three primes:36 SDK calls/nine exports. All subsequent exported proofs pass independent Gnark verification,164-byte length, pinned public binding and freshness against7,260 prior identities and new exports. Helpers compile before captures; no helper/build/hash/archive/verifier overlaps timed processes.\n\n");
 writeln!(md,"Total **{} SDK requests**, **{} distinct independently verified exports**, **{} proof/public members**; proof ledger **7,260 → {}**. All170 production files and the accepted SDK remain unchanged. The all-eight CPU10× objective remains active and unproven.\n",a["sdk_requests"],proofs,proofs*2,a["next_prior_count"]).unwrap();
 md.push_str("No new AWS/Aeglos, phone, TEE, giant-circuit, swap, minimum-RAM, pressure, concurrency or throughput qualification is claimed.\n\n");
 for(name,p)in [("reused fresh",r.join("fresh-control-artifacts.json")),("tree",r.join("native/tree/artifacts.json"))]{let b=read(p);writeln!(md,"{name} executable: `{}`; SHA-256 `{}`.\n",b["binary"].as_str().unwrap(),b["binary_sha256"].as_str().unwrap()).unwrap();}
 md.push_str("[Design](artifacts/design.md), [source audit](artifacts/implementation-audit.json), [edits](artifacts/edits.json), [context audit](artifacts/context-audit.json), [screen analysis](artifacts/screen-analysis.json), [native tests](artifacts/native/core/tests.json), [proof inventory](artifacts/proof-inventory.json), [artifact hashes](artifact-index.json).\n");
 fs::create_dir_all(d).unwrap();fs::write(d.join("README.md"),md).unwrap();fs::copy("/tmp/zopro-grouping-module/production-source-manifest.json",r.join("accepted-source-manifest.json")).unwrap();
 let mut index=BTreeMap::new();archive(r,r,&d.join("artifacts"),&mut index);for(p,h)in &index{assert_eq!(&hash(d.join("artifacts").join(p)),h);}for(p,h)in inventory.as_object().unwrap(){assert_eq!(hash(d.join("artifacts").join(Path::new(p).strip_prefix(r).unwrap())),h.as_str().unwrap());}save(d.join("artifact-index.json"),&json!(index));println!("{}archive hashes;{}proof/public members checked;nextprior{}",index.len(),proofs*2,a["next_prior_count"]);
}
fn archive(root:&Path,here:&Path,dest:&Path,index:&mut BTreeMap<String,String>){let mut paths:Vec<_>=fs::read_dir(here).unwrap().map(|e|e.unwrap().path()).collect();paths.sort();for p in paths{let rel=p.strip_prefix(root).unwrap();let s=rel.display().to_string();if s.starts_with("target-"){continue;}if p.is_dir(){archive(root,&p,dest,index);continue;}if s.starts_with("candidate/")&&!["candidate/crates/zopro-core/src/msm.rs"].contains(&s.as_str()){continue;}if !["json","jsonl","rs","md","txt","log","proof","public"].iter().any(|x|p.extension().is_some_and(|e|e==*x)){continue;}let q=dest.join(rel);fs::create_dir_all(q.parent().unwrap()).unwrap();fs::copy(&p,&q).unwrap();let h=hash(&q);assert_eq!(h,hash(&p));index.insert(s,h);}}
